import java.util.*;
public class Solution{public static void main(String[]a){Scanner sc=new Scanner(System.in);int n=sc.nextInt();sc.nextLine();String[]files=new String[n];for(int i=0;i<n;i++)files[i]=sc.nextLine().trim();String ext=sc.nextLine().trim();boolean found=false;for(String f:files)if(f.endsWith("."+ext)){System.out.println(f);found=true;}if(!found)System.out.println("No Records Found");}}
